from rich.highlighter import ReprHighlighter
from rich.text import Text

def test_url_with_at():
    highlighter = ReprHighlighter()
    text = Text("https://user:pass@example.com")
    highlighter.highlight(text)

    # We expect the whole thing to be highlighted as a URL
    # If it's broken, it might only highlight up to the '@' or not at all.
    for span in text.spans:
        print(f"Span: {span}")

    # Expected: Span(0, 27, "repr.url")
    assert any(span.style == "repr.url" and span.start == 0 and span.end == 27 for span in text.spans)

if __name__ == "__main__":
    try:
        test_url_with_at()
        print("Test passed!")
    except AssertionError:
        print("Test failed!")
    except Exception as e:
        print(f"An error occurred: {e}")

